from http.client import HTTPConnection
import json,tempfile,threading,unittest
from pathlib import Path
from uuid import uuid4
from novel_writer.ui.server import create_server
from test_book_ai import supplier

class ChapterWritingHttpTests(unittest.TestCase):
 def setUp(self):
  self.temp=tempfile.TemporaryDirectory(prefix='novel-writing-http-');self.addCleanup(self.temp.cleanup);root=Path(self.temp.name);self.server=create_server(root/'fiction.sqlite3',port=0,provider_path=root/'fiction.dpapi',enable_model_generation=True);self.thread=threading.Thread(target=self.server.serve_forever,kwargs={'poll_interval':.01},daemon=True);self.thread.start();self.addCleanup(self.stop);code,state=self.request('POST','/api/projects',dict(title='虚构初稿HTTP'));self.assertEqual(code,201);self.pid=state['document']['project']['id'];code,state=self.request('POST','/api/projects/'+self.pid+'/actions',dict(action='add_chapter',fields=dict(title='空章'),expected_revision=state['revision']));self.cid=state['document']['chapters'][0]['id'];self.base='/api/projects/'+self.pid
 def stop(self):self.server.shutdown();self.server.server_close();self.thread.join(2)
 def request(self,method,path,payload=None,*,token=True):
  client=HTTPConnection('127.0.0.1',self.server.server_port,timeout=5);headers={'Content-Type':'application/json'}
  if token:headers['X-Novel-Token']=self.server.token
  try:client.request(method,path,json.dumps(payload) if payload is not None else None,headers);response=client.getresponse();return response.status,json.loads(response.read())
  finally:client.close()
 def options(self):return dict(chapter_id=self.cid,mode='draft',context_options=dict(chapter_id=self.cid,budget_chars=6000),instruction='真实HTTP冻结',target_chars=300,required_literals=['门'],forbidden_literals=[])
 def test_preview_is_read_only_and_strict_fields_and_token_guard_apply_to_new_routes(self):
  before=self.request('GET',self.base)[1];options=self.options();self.assertEqual(self.request('POST',self.base+'/chapter-writing/preview',options,token=False)[0],403);code,preview=self.request('POST',self.base+'/chapter-writing/preview',options);self.assertEqual(code,200,preview);self.assertFalse(preview['model_request_sent']);self.assertEqual(self.request('GET',self.base)[1],before);self.assertEqual(self.request('POST',self.base+'/chapter-writing/preview',dict(options,endpoint='http://private.invalid'))[0],422);self.assertEqual(self.request('POST',self.base+'/chapter-writing/preview',dict(options,chapter_id=str(uuid4())))[0],422)
 def test_shared_execute_correction_review_and_adoption_cannot_skip_new_review_confirmation(self):
  with supplier(output='门前的HTTP候选。') as wire:
   connection=self.server.providers.save_custom(id=str(uuid4()),name='虚构HTTP正文模型',base_url=wire['url'],protocol='openai-chat',model_id='fiction-http-writing',api_key='fiction-http-writing-key',allow_local=True);options=self.options();code,source=self.request('POST',self.base+'/chapter-writing/preview',options);self.assertEqual(code,200,source);profile=dict(adapter_id='configured-http-v2',connection_id=connection['id'],model_id=connection['model_id'],temperature=.3,max_tokens=512,budget_limit=1.0,allow_unknown_cost=True,prompt_version='rewrite-1');request=dict(request_id=str(uuid4()),source_options=options,source_sha256=source['source_sha256'],model_options=profile,max_output_chars=2000,timeout_ms=2000,retry_of=None);code,prepared=self.request('POST',self.base+'/chapter-writing/prepare',request);self.assertEqual(code,201,prepared);task=prepared['task'];base=self.base+'/tasks/'+task['id'];self.assertEqual(wire['calls'],[]);self.assertEqual(self.request('POST',base+'/execute',dict(confirm_external=True,request_sha256='0'*64))[0],422);code,_=self.request('POST',base+'/execute',dict(confirm_external=True,request_sha256=task['frozen']['parameters']['binding']['request_sha256']));self.assertEqual(code,202);self.server.task_coordinator.wait_idle(5);done=self.request('GET',base)[1];self.assertEqual(done['task']['status'],'succeeded');state=self.request('GET',self.base)[1];legacy=dict(candidate_id=done['task']['candidate_id'],adoption_id=str(uuid4()),expected_revision=state['revision'],authorize_confirmed=False);self.assertEqual(self.request('POST',base+'/adopt',legacy)[0],422);self.assertEqual(self.request('GET',self.base)[1]['document']['chapters'][0]['content'],'');code,edit=self.request('POST',base+'/writing-correction',dict(operation_id=str(uuid4()),candidate_id=done['task']['candidate_id'],text='作者修正的门前新稿。'));self.assertEqual(code,201,edit);code,review=self.request('POST',base+'/writing-review',dict(candidate_id=done['task']['candidate_id'],correction_id=edit['id']));self.assertEqual(code,200,review);request=dict(legacy,expected_revision=review['revision'],correction_id=edit['id'],review_id=review['review_id'],confirmed_review=True);code,receipt=self.request('POST',base+'/adopt',request);self.assertEqual(code,200,receipt);after=self.request('GET',self.base)[1];self.assertEqual(after['document']['chapters'][0]['content'],'作者修正的门前新稿。');self.assertEqual(self.request('POST',base+'/adopt',request),(200,receipt));self.assertEqual(self.request('GET',self.base)[1],after);self.assertEqual(len(wire['calls']),1)

if __name__=='__main__':unittest.main()
